import{c as a,Q as t,j as r,m as i}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"HarmBench: A Standardized Evaluation Framework for Automated Red Teaming and Robust Refusal","description":"","frontmatter":{"url":"https://arxiv.org/abs/2402.04249","title":"HarmBench: A Standardized Evaluation Framework for Automated Red Teaming and Robust Refusal","archived_date":"2026-06-09T00:00:00.000Z","arxiv_id":2402.04249,"authors":["Mantas Mazeika","Long Phan","Xuwang Yin","Andy Zou","Zifan Wang","Norman Mu","Elham Sakhaee","Nathaniel Li","Steven Basart","Bo Li","David Forsyth","Dan Hendrycks"],"pdf_path":"pdfs/2402.04249.pdf","published_date":"2024-01-01T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2024-02-06-harmbench-automated-red-teaming-2402-04249.md","filePath":"research/papers/2024-02-06-harmbench-automated-red-teaming-2402-04249.md","lastUpdated":1785909234000}'),n={name:"research/papers/2024-02-06-harmbench-automated-red-teaming-2402-04249.md"};function s(o,e,l,d,c,h){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="harmbench-a-standardized-evaluation-framework-for-automated-red-teaming-and-robust-refusal" tabindex="-1">HarmBench: A Standardized Evaluation Framework for Automated Red Teaming and Robust Refusal <a class="header-anchor" href="#harmbench-a-standardized-evaluation-framework-for-automated-red-teaming-and-robust-refusal" aria-label="Permalink to &quot;HarmBench: A Standardized Evaluation Framework for Automated Red Teaming and Robust Refusal&quot;">​</a></h1><p><strong>Authors:</strong> Mantas Mazeika, Long Phan, Xuwang Yin, Andy Zou, Zifan Wang, Norman Mu, Elham Sakhaee, Nathaniel Li, Steven Basart, Bo Li, David Forsyth, Dan Hendrycks</p><p><strong>Year:</strong> 2024</p><p><strong>Venue:</strong> ICML 2024</p><p><strong>ArXiv:</strong> <a href="https://arxiv.org/abs/2402.04249" target="_blank" rel="noreferrer">https://arxiv.org/abs/2402.04249</a></p><p><strong>Code:</strong> <a href="https://github.com/centerforaisafety/HarmBench" target="_blank" rel="noreferrer">https://github.com/centerforaisafety/HarmBench</a></p><hr><h2 id="full-abstract" tabindex="-1">Full Abstract <a class="header-anchor" href="#full-abstract" aria-label="Permalink to &quot;Full Abstract&quot;">​</a></h2><p>Automated red teaming holds substantial promise for uncovering and mitigating the risks associated with the malicious use of large language models (LLMs), yet the field lacks a standardized evaluation framework to rigorously assess new methods. To address this issue, we introduce HarmBench, a standardized evaluation framework for automated red teaming. We identify key properties previously unaccounted for in red teaming evaluations and systematically integrate these properties into HarmBench. Using HarmBench, we conduct a large-scale comparison of 18 red teaming methods and 33 target LLMs and defenses, yielding novel insights into the relative effectiveness of attacks and defenses. We also introduce a highly efficient adversarial training method that greatly enhances LLM robustness across a wide range of attacks, demonstrating how HarmBench enables codevelopment of attacks and defenses. We open source HarmBench at <a href="https://github.com/centerforaisafety/HarmBench" target="_blank" rel="noreferrer">https://github.com/centerforaisafety/HarmBench</a>.</p><hr><h2 id="key-contributions" tabindex="-1">Key Contributions <a class="header-anchor" href="#key-contributions" aria-label="Permalink to &quot;Key Contributions&quot;">​</a></h2><ul><li><strong>First standardized red teaming benchmark:</strong> HarmBench establishes reproducible, comparable safety evaluations for automated red teaming, filling a critical methodological gap in the field.</li><li><strong>Four-category harm taxonomy:</strong> Harmful behaviors are categorized into standard behaviors, contextual behaviors, copyright behaviors, and multimodal behaviors — each with distinct evaluation criteria and attack surface profiles.</li><li><strong>Large-scale empirical comparison:</strong> Comparative study of 18 red teaming methods against 33 target LLMs and defenses, yielding the most comprehensive systematic insights into attack-defense dynamics published to date.</li><li><strong>Attack Success Rate (ASR) metrics:</strong> Introduced robust ASR metrics using a fine-tuned LLaMA-2 classifier to judge harmful completions, reducing reliance on brittle string-matching heuristics.</li><li><strong>Efficient adversarial training:</strong> Developed an adversarial training method that significantly enhances LLM robustness across diverse attack types, demonstrating viable paths toward more resistant safety alignment.</li><li><strong>Open-source ecosystem:</strong> Released framework, datasets, and evaluation tooling enabling the community to co-develop attacks and defenses in a reproducible setting.</li><li><strong>Novel cross-attack insights:</strong> Revealed that no single attack dominates across all target models, and that defenses providing broad robustness against one attack class do not necessarily generalize to others.</li></ul><hr><h2 id="methodology" tabindex="-1">Methodology <a class="header-anchor" href="#methodology" aria-label="Permalink to &quot;Methodology&quot;">​</a></h2><p>HarmBench is structured around a modular evaluation pipeline that decouples attack generation, target model inference, and harm judgment. Attacks submit candidate completions to a shared judge model (a fine-tuned LLaMA-2 classifier), ensuring consistent harm detection across diverse attack strategies. This design allows 18 attack methods — spanning gradient-based approaches (GCG, AutoDAN), prompt optimization methods (PAIR, TAP), and human-engineered jailbreaks — to be compared on identical footing against the same target model and defense configurations.</p><p>The benchmark covers four functional categories of harmful behaviors. Standard behaviors are direct harmful requests (e.g., synthesis instructions for dangerous substances). Contextual behaviors require the model to produce harm only in specific conversational contexts. Copyright behaviors target verbatim reproduction of protected text. Multimodal behaviors involve image-conditioned attacks on vision-language models. This taxonomy ensures the benchmark captures the full breadth of real-world adversarial scenarios rather than collapsing all harm into a single dimension.</p><p>Adversarial training is implemented via R2D2 (Robust Refusal Dynamic Defense), which integrates GCG attack generation directly into the training loop. By continuously generating and training against fresh adversarial suffixes, R2D2 avoids the static adversarial training failure mode where robustness degrades when attackers adapt. The approach is computationally efficient relative to prior adversarial training proposals and achieves broad-spectrum robustness improvements.</p><hr><h2 id="main-results" tabindex="-1">Main Results <a class="header-anchor" href="#main-results" aria-label="Permalink to &quot;Main Results&quot;">​</a></h2><ul><li>Across 18 attacks and 33 models, no single attack achieves universally high ASR; gradient-based attacks (GCG, AutoDAN) perform strongest against open-source models but transfer poorly to closed APIs.</li><li>PAIR and TAP (LLM-as-attacker methods) achieve competitive ASR against closed-source models where gradients are unavailable.</li><li>Defenses vary substantially in effectiveness: perplexity filtering reduces gradient-based attacks but is ineffective against semantically natural jailbreaks.</li><li>R2D2 adversarial training achieves the largest robustness gains — over 90% ASR reduction on GCG attacks — while maintaining near-baseline performance on benign queries.</li><li>Multimodal attacks (image-conditioned jailbreaks) exhibit higher baseline ASR than text-only attacks against vision-language models, highlighting an underexplored attack surface.</li><li>Copyright and contextual behavior categories are substantially harder to defend than standard behaviors, suggesting that current safety training disproportionately targets the standard harm category.</li></ul><hr><h2 id="limitations-and-future-work" tabindex="-1">Limitations and Future Work <a class="header-anchor" href="#limitations-and-future-work" aria-label="Permalink to &quot;Limitations and Future Work&quot;">​</a></h2><ul><li><strong>Static benchmark drift:</strong> As models and attacks evolve, static benchmark behaviors may become unrepresentative of frontier risks; continuous benchmark updating is needed.</li><li><strong>Judge model limitations:</strong> The LLaMA-2 classifier judge can be fooled by obfuscated outputs that evade harm detection while still conveying harmful information.</li><li><strong>Closed-model coverage:</strong> Evaluation of closed-source models (GPT-4, Claude) is limited to black-box API access, precluding gradient-based attacks and full defense analysis.</li><li><strong>Multimodal coverage:</strong> Multimodal attack coverage is nascent; as vision-language models proliferate, broader multimodal harm taxonomies are needed.</li><li><strong>Adversarial training scalability:</strong> R2D2 training is evaluated at 7B–13B parameter scales; scaling behavior to frontier model sizes remains uncharacterized.</li></ul><hr><h2 id="why-this-matters-for-ai-practitioners" tabindex="-1">Why This Matters for AI Practitioners <a class="header-anchor" href="#why-this-matters-for-ai-practitioners" aria-label="Permalink to &quot;Why This Matters for AI Practitioners&quot;">​</a></h2><p>HarmBench is the field&#39;s first credible attempt to bring benchmark rigor to red teaming — a domain that previously relied on ad hoc, incomparable evaluations. For practitioners, this means:</p><ul><li><strong>Reproducible safety comparisons:</strong> Teams can now benchmark their defenses against a common attack suite rather than self-selected methods, enabling honest capability claims.</li><li><strong>Taxonomy-driven risk assessment:</strong> The four-category taxonomy maps cleanly to real deployment risk profiles (direct harm, contextual harm, IP risk, multimodal risk), supporting structured threat modeling.</li><li><strong>Defense co-development:</strong> The open-source framework accelerates the attack-defense research cycle, reducing time from attack publication to viable defense.</li><li><strong>Adversarial training template:</strong> R2D2&#39;s efficient training loop provides a practical starting point for practitioners seeking to harden models beyond RLHF-level alignment.</li></ul><p>The work establishes a methodological foundation that subsequent red teaming research — including WildTeaming and automated jailbreak frameworks — builds upon directly.</p>',28)])])}const g=a(n,[["render",s]]);export{u as __pageData,g as default};
